/**
 * The SYNTHETIC print of the men's test tee (slice M3, defect 5): generated by this file, from nothing but code. No photo,
 * no product, no third-party artwork; licence: CC0 1.0 (public domain dedication), recorded in the bundle's qa.json
 * (`texture.licence`). It exists to show that the tee's UVs (`pomUv.ts`) carry a print at its real size and a flat-lay
 * photo onto the right panel, not as a design.
 *
 * - `stripePrint`: a repeating breton stripe in cm (ink stripes on cream), one phase for the whole tee: body panels by
 *   their `v` (cm down from the high point shoulder), sleeves by theirs (cm down from the armhole).
 * - `syntheticFlatLay`: two rasters drawn as if a shop had photographed the tee flat, front and back, at a known scale:
 *   the same stripes plus a coral sun on the chest (front) and a small coral tab under the neck (back). They go through the
 *   flat-lay projection (`flatLayPainter`), the path a merchant's real photo would take.
 *
 * Colours are the design tokens (handoff §7): coral #FF5A3C, cream #F5EFE7, ink #1A1612.
 */
import type { Painter, Rgb, FlatLayCalibration } from './pomUv';

export const PRINT_LICENCE = 'CC0-1.0';
export const PRINT_SOURCE = 'synthetic: generated by spikes/garment-engine/src/pomPrint.ts (no photo, no product, no third-party artwork)';

const CORAL: [number, number, number] = [0xff, 0x5a, 0x3c];
const CREAM: [number, number, number] = [0xf5, 0xef, 0xe7];
const INK: [number, number, number] = [0x1a, 0x16, 0x12];

/** Stripe repeat and width, cm. */
export const STRIPE_PERIOD_CM = 4.5;
export const STRIPE_WIDTH_CM = 1.2;

const mix = (a: [number, number, number], b: [number, number, number], t: number): [number, number, number] => [Math.round(a[0] + (b[0] - a[0]) * t), Math.round(a[1] + (b[1] - a[1]) * t), Math.round(a[2] + (b[2] - a[2]) * t)];
/** Coverage of an edge `d` cm inside (positive) a shape, antialiased over `aa` cm. */
const cover = (d: number, aa: number): number => Math.min(1, Math.max(0, 0.5 + d / aa));

function stripeAt(v: number, aa: number): [number, number, number] {
  const ph = ((v % STRIPE_PERIOD_CM) + STRIPE_PERIOD_CM) % STRIPE_PERIOD_CM;
  // Distance inside the stripe [0, width], antialiased.
  const inside = Math.min(ph, STRIPE_WIDTH_CM - ph);
  return mix(CREAM, INK, cover(inside, aa));
}

/** The repeating stripe on every panel. `aa`: antialiasing width, cm (about one texel). */
export function stripePrint(aa = 0.15): Painter {
  return (_panel, _u, v) => stripeAt(v, aa);
}

/** A coral sun: a disc of radius `r` and twelve rays out to 1.8 r, centred at (cu, cv) cm. */
function sun(u: number, v: number, cu: number, cv: number, r: number, aa: number): number {
  const d = Math.hypot(u - cu, v - cv);
  const disc = cover(r - d, aa);
  const a = Math.atan2(v - cv, u - cu);
  const ray = Math.abs(Math.sin(6 * a)) * d;
  const rays = d > 1.25 * r && d < 1.8 * r ? cover(0.35 - ray, aa) : 0;
  return Math.max(disc, rays);
}

/** The synthetic front and back flat-lay "photos" (`Rgb`), drawn at `pxPerCm`, with their calibration. */
export function syntheticFlatLay(pxPerCm = 8): { front: { photo: Rgb; cal: FlatLayCalibration }; back: { photo: Rgb; cal: FlatLayCalibration } } {
  const W = Math.round(80 * pxPerCm), H = Math.round(90 * pxPerCm);
  const cal: FlatLayCalibration = { pxPerCm, hpsCentrePx: [W / 2, 6 * pxPerCm] };
  const aa = 1.2 / pxPerCm;
  const draw = (motif: (u: number, v: number) => number): Rgb => {
    const data = new Uint8Array(W * H * 3);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const u = (x + 0.5 - cal.hpsCentrePx[0]) / pxPerCm, v = (y + 0.5 - cal.hpsCentrePx[1]) / pxPerCm;
      data.set(mix(stripeAt(v, aa), CORAL, motif(u, v)), 3 * (y * W + x));
    }
    return { width: W, height: H, data };
  };
  // Front: a sun on the left chest of the wearer (the picture's right), 9 cm off centre, 17 cm under the HPS.
  const front = draw((u, v) => sun(u, v, 9, 17, 3.2, aa));
  // Back: a tab 4 × 2.5 cm, 6 cm under the HPS on the centre line.
  const back = draw((u, v) => cover(Math.min(2 - Math.abs(u), 1.25 - Math.abs(v - 6)), aa));
  return { front: { photo: front, cal }, back: { photo: back, cal } };
}

export const PRINT_BACKGROUND = CREAM;
